/**
 * Bagisto "auth" helpers.
 *
 * Bagisto does NOT use OAuth2's authorization-code flow for third-party
 * integrations. Credentials are Bearer tokens (either OAuth2 password-grant
 * tokens or personal access tokens) generated by the store admin. The adapter
 * therefore:
 *
 *  - Throws descriptively from `getAuthUrl` and `exchangeCode` so ambiguous
 *    callers fail loudly.
 *  - Supports token refresh via POST /oauth/token when a refreshToken is
 *    present in the stored credentials.
 *
 * Configure via POST /v1/connections with:
 * `{ platform: 'bagisto', credentials: { accessToken, extra: { baseUrl } } }`
 *
 * Docs: https://devdocs.bagisto.com/
 */

import type { Credentials } from '@opensteward/shared'

export function getAuthUrl(_state: string): string {
  throw new Error(
    'Bagisto uses Bearer token auth — configure via /v1/connections with ' +
      '{ platform: "bagisto", credentials: { accessToken, extra: { baseUrl } } }.',
  )
}

export async function exchangeCode(
  _code: string,
  _redirectUri: string,
): Promise<Credentials> {
  throw new Error(
    'Bagisto uses Bearer token auth — no code exchange. ' +
      'POST credentials directly to /v1/connections with ' +
      '{ platform: "bagisto", credentials: { accessToken, extra: { baseUrl } } }.',
  )
}

export async function refreshCredentials(credentials: Credentials): Promise<Credentials> {
  const refreshToken = credentials.refreshToken
  if (!refreshToken) {
    // No refresh token — return as-is (static PAT flow).
    return credentials
  }

  const baseUrl = (credentials.extra?.['baseUrl'] as string | undefined)?.replace(/\/$/, '')
  const clientId = credentials.extra?.['clientId'] as string | undefined
  const clientSecret = credentials.extra?.['clientSecret'] as string | undefined

  if (!baseUrl) {
    throw new Error(
      'Bagisto refreshCredentials: credentials.extra.baseUrl is required',
    )
  }

  const params = new URLSearchParams({
    grant_type: 'refresh_token',
    refresh_token: refreshToken,
    ...(clientId ? { client_id: clientId } : {}),
    ...(clientSecret ? { client_secret: clientSecret } : {}),
  })

  const response = await fetch(`${baseUrl}/oauth/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
  })

  if (!response.ok) {
    throw new Error(
      `Bagisto token refresh failed: ${response.status} ${response.statusText}`,
    )
  }

  const body = (await response.json()) as {
    access_token?: string
    refresh_token?: string
    expires_in?: number
    token_type?: string
  }

  if (!body.access_token) {
    throw new Error('Bagisto token refresh: no access_token in response')
  }

  return {
    ...credentials,
    accessToken: body.access_token,
    refreshToken: body.refresh_token ?? credentials.refreshToken,
    expiresAt:
      body.expires_in != null
        ? new Date(Date.now() + body.expires_in * 1000)
        : credentials.expiresAt,
  }
}
